 * word the create clears; the ItemType's unk40 Node is attached under it as with
 * SNodeItemType_newItem. */
typedef struct EddColourItem {
    /* 0x00 */ ColourItem base;
    /* 0x3C */ s32 unk3C;
} EddColourItem;

typedef char EddColourItem_size_check[sizeof(EddColourItem) == 0x40 ? 1 : -1];

extern int gl_func_00000000();
extern char D_00000000;
typedef struct { int a, b, c, d; } Quad4;
typedef struct { int a, b, c; } Tri3i;
typedef struct { float x, y, z; } Vec3;

/* USO entry-0: leading `beq zero,zero,+0x6F00` trampoline (loader-patched
 * at runtime) followed by the standard -O2 int-reader template body. The
 * trampoline word is injected post-cc via PREFIX_BYTES (see Makefile +
 * scripts/inject-prefix-bytes.py).
 *
 * 2026-05-27: confirmed bytes IDENTICAL with expected/.o (objdump -d
 * both shows the same 16 instructions @ 0x00 — trampoline + body). The
 * 93.75% fuzzy in report.json comes from RELOC-PRESENCE diff, not
 * byte-diff: our .o emits R_MIPS_HI16/LO16/26 for D_00000000 +
 * gl_func_00000000; expected/.o has no relocs (captured pre-reloc — raw
 * .word USO form). Same uso_raw_word-vs-reloc cap class as other USO
 * func_00000000 entries. Real fix needs USO spimdisasm migration
 * (focused-session per project_1080_uso_spimdisasm_migration_todo). No
 * C lever; do NOT re-grind. */
void eddproc_uso_func_00000000(int *dst) {
    int buf[2];
    /* UNNAMED: sentinel this is the sentinel-named Text+0 function (PREFIX_BYTES trampoline at word 0), which the call resolver cannot place; the ROM jal at Text+0x18 is fs_gdlReadFile */
    gl_func_00000000(&D_00000000, buf, 4);
    *dst = buf[0];
}

void fs_gdlReadFloat_edd_00000040(float *dst) {
    float buf[2];
    CALL(fs_gdlReadFile)(&D_00000000, buf, 4);
    *dst = buf[0];
}

void fs_gdlReadQuad_edd_0000007C(Quad4 *dst) {
    Quad4 buf;
    CALL(fs_gdlReadFile)(&D_00000000, &buf, 16);
    *dst = buf;
}

void fs_gdlReadVec3_edd_000000D4(Vec3 *dst) {
    int pad_top[1];
    Tri3i raw;
    int pad_mid[2];
    Tri3i tmp;
    int pad_bot[2];
    CALL(fs_gdlReadFile)(&D_00000000, &raw, 12);
    tmp = raw;
    dst->x = *(float*)&tmp.a;
    dst->y = *(float*)&tmp.b;
    dst->z = *(float*)&tmp.c;
}

